// «Мины»: поле 5 × 5, 3 мины расставляются в start тремя вызовами rng; игрок открывает клетки и забирает выигрыш.
// Спецификация: games/mines/spec.md. Решения: decisions/mines.md (правила — D-001…D-009). Документация: games/mines/README.md.
import type { GameModule, Rng, Step } from '../../../platform/sdk/types.ts';
import { GameError } from '../../../platform/sdk/types.ts';

/** Число клеток поля 5 × 5 (D-002). */
export const CELL_COUNT = 25;

/** Число мин на поле, фиксировано (D-001). */
export const MINE_COUNT = 3;

/** Число безопасных клеток: открытие последней завершает раунд (D-006). */
export const SAFE_COUNT = CELL_COUNT - MINE_COUNT;

/** Доля выплаты после house edge 2 % (D-004). */
export const RTP = 0.98;

/** Нормализованные параметры раунда: у игры их нет (D-008). */
export type MinesParams = Record<string, never>;

/** Чем закончился раунд: мина, cashout или открыты все безопасные клетки. */
export type MinesOutcome = 'mine' | 'cashout' | 'cleared';

/** Состояние раунда (spec, раздел «Результат и выплата»). */
export interface MinesState {
  /** Клетки с минами, по возрастанию. */
  mines: number[];
  /** Открытые безопасные клетки в порядке открытия. */
  revealed: number[];
  /** Клетка с миной, на которой игрок проиграл, иначе `null`. */
  hit: number | null;
  /** Исход раунда, `null` пока раунд открыт. */
  outcome: MinesOutcome | null;
}

/** Ход игрока (D-007). */
export type MinesAction = { type: 'reveal'; cell: number } | { type: 'cashout' };

/** Что видит клиент (D-009). Поля `mines`, `hit`, `outcome` есть только после завершения раунда. */
export interface MinesView {
  mineCount: number;
  revealed: number[];
  multiplier: number;
  nextMultiplier: number | null;
  mines?: number[];
  hit?: number | null;
  outcome?: MinesOutcome | null;
}

function round2(x: number): number {
  return Math.round(x * 100) / 100;
}

function binom(n: number, k: number): number {
  let r = 1;
  for (let i = 1; i <= k; i++) r = (r * (n - k + i)) / i;
  return r;
}

/**
 * Множитель после `k` открытых безопасных клеток (D-004):
 * `M(0) = 1` (только для отображения), иначе `round2(0.98 × C(25, k) / C(22, k))`.
 */
export function multiplier(k: number): number {
  if (k <= 0) return 1;
  return round2((RTP * binom(CELL_COUNT, k)) / binom(SAFE_COUNT, k));
}

/** Расстановка мин частичной тасовкой Фишера — Йетса: ровно 3 вызова rng (D-003). */
function placeMines(rng: Rng): number[] {
  const c = Array.from({ length: CELL_COUNT }, (_, i) => i);
  for (let i = 0; i < MINE_COUNT; i++) {
    const j = i + Math.floor(rng.next() * (CELL_COUNT - i));
    const t = c[i] as number;
    c[i] = c[j] as number;
    c[j] = t;
  }
  return c.slice(0, MINE_COUNT).sort((a, b) => a - b);
}

function invalidAction(message: string): never {
  throw new GameError('INVALID_ACTION', message);
}

/** Проверяет ход до любых изменений; возвращает нормализованное действие. */
function parseAction(action: unknown, state: MinesState): MinesAction {
  if (typeof action !== 'object' || action === null || Array.isArray(action)) {
    invalidAction('Ход должен быть объектом { type, cell }');
  }
  const type = (action as { type?: unknown }).type;
  if (type === 'cashout') {
    if (state.revealed.length < 1) invalidAction('Забрать выигрыш можно после первой открытой клетки');
    return { type: 'cashout' };
  }
  if (type === 'reveal') {
    const cell = (action as { cell?: unknown }).cell;
    if (typeof cell !== 'number' || !Number.isInteger(cell) || cell < 0 || cell >= CELL_COUNT) {
      invalidAction('cell должен быть целым числом от 0 до 24');
    }
    if (state.revealed.includes(cell)) invalidAction('Клетка уже открыта');
    return { type: 'reveal', cell };
  }
  return invalidAction('Неизвестный тип хода');
}

/**
 * Серверный модуль «Мин».
 *
 * - `validateParams(params)` — `{}` для объекта или `undefined`, лишние поля отбрасываются;
 *   `null`, массив, строка, число → `GameError('INVALID_PARAMS')` (D-008).
 * - `start({ rng })` — 3 вызова `rng.next()`, расстановка мин, шаг `continue` (D-003).
 * - `action({ bet, state, action })` — `reveal`/`cashout`, rng не используется, `state` не меняется (D-005…D-007).
 * - `publicView(state, finished)` — до конца раунда без `mines`/`hit`/`outcome` (D-009).
 */
const game: GameModule<MinesParams, MinesState, unknown> = {
  id: 'mines',

  validateParams(params: unknown): MinesParams {
    if (params === undefined) return {};
    if (typeof params !== 'object' || params === null || Array.isArray(params)) {
      throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом');
    }
    return {};
  },

  start({ params, rng }: { bet: number; params: MinesParams; rng: Rng }): Step<MinesState> {
    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
    game.validateParams(params);
    const mines = placeMines(rng);
    return { status: 'continue', state: { mines, revealed: [], hit: null, outcome: null } };
  },

  action({ bet, state, action }: { bet: number; params: MinesParams; state: MinesState; action: unknown; rng: Rng }): Step<MinesState> {
    const a = parseAction(action, state);
    const mines = state.mines.slice();
    if (a.type === 'cashout') {
      const revealed = state.revealed.slice();
      return {
        status: 'finished',
        state: { mines, revealed, hit: null, outcome: 'cashout' },
        payout: bet * multiplier(revealed.length),
      };
    }
    if (mines.includes(a.cell)) {
      return {
        status: 'finished',
        state: { mines, revealed: state.revealed.slice(), hit: a.cell, outcome: 'mine' },
        payout: 0,
      };
    }
    const revealed = [...state.revealed, a.cell];
    if (revealed.length >= SAFE_COUNT) {
      return {
        status: 'finished',
        state: { mines, revealed, hit: null, outcome: 'cleared' },
        payout: bet * multiplier(revealed.length),
      };
    }
    return { status: 'continue', state: { mines, revealed, hit: null, outcome: null } };
  },

  publicView(state: MinesState, finished: boolean): MinesView {
    const k = state.revealed.length;
    const base = { mineCount: MINE_COUNT, revealed: state.revealed.slice(), multiplier: multiplier(k) };
    if (!finished) return { ...base, nextMultiplier: multiplier(k + 1) };
    return { ...base, nextMultiplier: null, mines: state.mines.slice(), hit: state.hit, outcome: state.outcome };
  },
};

/** Модуль игры `mines` (`GameModule`), который платформа загружает по `manifest.json`. */
export default game;
// Контракт серверного модуля «Мин» (games/mines/spec.md, SC-14; platform/sdk/types.ts).
// Проверяются публичные методы GameModule: число вызовов rng, неизменяемость state, сериализуемость, коды ошибок.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import game from '../server/index.ts';
import { GameError } from '../../../platform/sdk/types.ts';

/** rng, который отдаёт заданные числа и бросает, когда они кончились; считает вызовы. */
function countingRng(values: number[]) {
  let calls = 0;
  const rng = {
    next(): number {
      calls += 1;
      if (calls > values.length) throw new Error('rng: лишний вызов');
      return values[calls - 1] as number;
    },
  };
  return { rng, calls: () => calls };
}

function gameErrorCode(fn: () => unknown): string {
  try {
    const v = fn();
    throw new Error(`ожидалась GameError, а вызов вернул ${JSON.stringify(v)}`);
  } catch (e: any) {
    expect(e).toBeInstanceOf(GameError);
    return e.code;
  }
}

const P3 = { mines: 3 };
const START_STATE = { mines: [7, 12, 19], revealed: [], hit: null, outcome: null };
const range = (from: number, to: number) => Array.from({ length: to - from + 1 }, (_, i) => from + i);

describe('Мины: контракт модуля игры', () => {
  beforeEach(() => {
    vi.spyOn(Math, 'random').mockImplementation(() => {
      throw new Error('Math.random запрещён в игре');
    });
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('SC-14: id и validateParams — mines 1…24, по умолчанию 3, лишние поля отброшены', () => {
    expect(game.id).toBe('mines');
    expect(game.validateParams({ mines: 5, extra: 1 })).toEqual({ mines: 5 });
    expect(game.validateParams(undefined)).toEqual({ mines: 3 });
    expect(game.validateParams({})).toEqual({ mines: 3 });
    expect(game.validateParams({ extra: 1 })).toEqual({ mines: 3 });
    expect(game.validateParams({ mines: 1 })).toEqual({ mines: 1 });
    expect(game.validateParams({ mines: 24 })).toEqual({ mines: 24 });
    expect(game.validateParams({ mines: 3 })).toEqual({ mines: 3 });
  });

  it('SC-14: validateParams бросает GameError INVALID_PARAMS на неверные params и mines', () => {
    const bad: unknown[] = [
      null,
      [],
      'x',
      5,
      { mines: 0 },
      { mines: 25 },
      { mines: -3 },
      { mines: 2.5 },
      { mines: '5' },
      { mines: null },
    ];
    for (const p of bad) {
      expect(gameErrorCode(() => game.validateParams(p)), `params = ${JSON.stringify(p)}`).toBe('INVALID_PARAMS');
    }
  });

  it('SC-14: start с { mines: 3 } делает ровно 3 вызова rng, состояние сериализуемо, publicView не раскрывает мины', () => {
    const { rng, calls } = countingRng([0.5, 0.75, 0.25]);
    const step: any = game.start({ bet: 2, params: P3, rng });
    expect(calls()).toBe(3);
    expect(step.status).toBe('continue');
    expect(step).not.toHaveProperty('payout');
    expect(step.state).toEqual(START_STATE);
    expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
    expect(game.publicView(step.state, false)).toEqual({ mineCount: 3, revealed: [], multiplier: 1, nextMultiplier: 1.11 });
  });

  it('SC-14: start расставляет m мин по таблице спецификации за ровно m вызовов rng и хранит их отсортированными', () => {
    const cases: Array<[number, number[], number[]]> = [
      [3, [0.5, 0.75, 0.25], [7, 12, 19]],
      [3, [0, 0, 0], [0, 1, 2]],
      [3, [0.9999, 0.9999, 0.9999], [0, 1, 24]],
      [1, [0.5], [12]],
      [5, [0.5, 0.75, 0.25, 0, 0], [3, 4, 7, 12, 19]],
      [24, Array(24).fill(0), range(0, 23)],
      [24, Array(24).fill(0.9999), [...range(0, 22), 24]],
    ];
    for (const [m, values, mines] of cases) {
      const { rng, calls } = countingRng(values);
      const step: any = game.start({ bet: 1, params: { mines: m }, rng });
      expect(calls(), `m = ${m}, rng ${values}`).toBe(m);
      expect(step.status).toBe('continue');
      expect(step.state, `m = ${m}, rng ${values}`).toEqual({ mines, revealed: [], hit: null, outcome: null });
      expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
    }
  });

  it('SC-14: start с { mines: 1 } — 1 вызов rng, мина 12, publicView с множителем от одной мины', () => {
    const { rng, calls } = countingRng([0.5]);
    const step: any = game.start({ bet: 1, params: { mines: 1 }, rng });
    expect(calls()).toBe(1);
    expect(step.state.mines).toEqual([12]);
    expect(game.publicView(step.state, false)).toEqual({ mineCount: 1, revealed: [], multiplier: 1, nextMultiplier: 1.02 });
  });

  it('SC-14: start с { mines: 24 } и rng = 0 — ровно 24 вызова, мины 0…23', () => {
    let calls = 0;
    const rng = {
      next(): number {
        calls += 1;
        return 0;
      },
    };
    const step: any = game.start({ bet: 1, params: { mines: 24 }, rng });
    expect(calls).toBe(24);
    expect(step.state.mines).toEqual(range(0, 23));
    expect(game.publicView(step.state, false)).toEqual({ mineCount: 24, revealed: [], multiplier: 1, nextMultiplier: 24.5 });
  });

  it('SC-14: start с неверным mines в обход validateParams — INVALID_PARAMS до rng', () => {
    for (const params of [{ mines: 0 }, { mines: 30 }]) {
      const { rng, calls } = countingRng(Array(30).fill(0));
      expect(gameErrorCode(() => game.start({ bet: 1, params, rng })), `params = ${JSON.stringify(params)}`).toBe(
        'INVALID_PARAMS',
      );
      expect(calls(), `params = ${JSON.stringify(params)}`).toBe(0);
    }
  });

  it('SC-14: action reveal безопасной клетки не вызывает rng и не меняет переданный state', () => {
    const { rng: startRng } = countingRng([0.5, 0.75, 0.25]);
    const state = (game.start({ bet: 2, params: P3, rng: startRng }) as any).state;
    const snapshot = structuredClone(state);
